 async function deleteLearningData(){if(!ready){setNotice('Wait for account loading to finish before deleting data.');return;}if(!window.confirm('Delete your workspace, evidence, backups, and group memberships? Export anything you want to keep first.'))return;const wasCloud=cloud.current;deleting.current=true;cloud.current=false;syncEpoch.current++;if(saveTimer.current){clearTimeout(saveTimer.current);saveTimer.current=null;}setSync('Deleting your learning data…');try{await saveChain.current.catch(()=>{});if(user){const r=await fetch('/api/learn',{method:'DELETE'});if(!r.ok)throw new Error('Account deletion could not complete. Your device copy is preserved; please retry.');}localStorage.removeItem(storageKey.current);localStorage.removeItem(storageKey.current+'-backup-before-cloud-merge');setHasBackup(false);revision.current=0;latestState.current=initialLearner;skipNextSave.current=true;cloud.current=!!user;deleting.current=false;setState({...initialLearner});setReady(true);setSync('Learning data deleted');setNotice('Your learning data and device backups have been deleted.')}catch(e){deleting.current=false;cloud.current=wasCloud;setState(s=>({...s}));setSync('Deletion failed · device progress preserved');setNotice((e as Error).message)}}
